export const referenceTexts: Record<string, string> = {
  "10": "<!-- source: 10_Laborator_KOC2_2026-10-15.docx -->\n\nFIKTIVNÍ PACIENTKA – testovací data pro Rakathon 2026\n\nKOC Nemocnice Lipová (fiktivní)\n\nOddělení klinické biochemie a hematologie\n\nNemocniční 15, 140 00 Praha 4\n\nVýsledky laboratorního vyšetření\n\nPacientka: Alena Procházková, RČ 635722/1013, ZP 211\n\nIndikující lékař: MUDr. Lenka Marková, onkologická ambulance KOC\n\nOdběr: 15. 10. 2026 7:45\n\nKREVNÍ OBRAZ\n\n| Vyšetření | Výsledek | Jednotky | Ref. meze |\n| --- | --- | --- | --- |\n| Leukocyty | 8,9 | 10⁹/l | 4,0–10,0 |\n| Erytrocyty | 3,98 | 10¹²/l | 3,80–5,20 |\n| Hemoglobin | 118 L | g/l | 120–160 |\n| Hematokrit | 0,35 | 1 | 0,35–0,47 |\n| MCV | 88 | fl | 82–98 |\n| Trombocyty | 312 | 10⁹/l | 150–400 |\n| Neutrofily | 68 | % | 45–70 |\n| Lymfocyty | 22 | % | 20–45 |\n\nBIOCHEMIE\n\n| Vyšetření | Výsledek | Jednotky | Ref. meze |\n| --- | --- | --- | --- |\n| Sodík | 137 | mmol/l | 136–145 |\n| Draslík | 4,1 | mmol/l | 3,5–5,1 |\n| Vápník | 2,31 | mmol/l | 2,15–2,55 |\n| Urea | 4,6 | mmol/l | 2,8–8,1 |\n| Kreatinin | 74 | µmol/l | 45–84 |\n| eGFR (CKD-EPI) | 1,25 | ml/s/1,73 m² | > 1,0 |\n| Glukóza | 6,2 H | mmol/l | 3,9–5,6 |\n| Bilirubin celkový | 23 H | µmol/l | 2–17 |\n| Bilirubin konjugovaný | 6 H | µmol/l | 0–5 |\n| ALT | 1,62 H | µkat/l | 0,10–0,60 |\n| AST | 1,20 H | µkat/l | 0,10–0,60 |\n| GGT | 5,00 H | µkat/l | 0,10–0,70 |\n| ALP | 3,40 H | µkat/l | 0,58–1,75 |\n| Celková bílkovina | 66 | g/l | 64–83 |\n| Albumin | 36 | g/l | 35–52 |\n| CRP | 18 H | mg/l | 0–5 |\n\nNÁDOROVÉ MARKERY\n\n| Vyšetření | Výsledek | Jednotky | Ref. meze |\n| --- | --- | --- | --- |\n| CA 19-9 | 312 H | kU/l | < 37 |\n| CEA | 4,1 | µg/l | < 5,0 |\n| CA 125 | 48 H | kU/l | < 35 |\n\nVydáno: 15. 10. 2026\n\nIng. Martina Šebestová\n\nodborný pracovník laboratoře\n",
  "11": "<!-- source: 11_Histologie_KOC2_2026-10-19.docx -->\n\nFIKTIVNÍ PACIENTKA – testovací data pro Rakathon 2026\n\nKOC Nemocnice Lipová (fiktivní)\n\nÚstav patologie\n\nNemocniční 15, 140 00 Praha 4\n\nBioptický nález\n\nPacientka: Alena Procházková, RČ 635722/1013, ZP 211\n\nČíslo vyšetření: B-2026/15921\n\nMateriál: ložisko hlavy pankreatu, EUS-FNB 22G (odběr 20. 10. 2026)\n\nOdesílající: MUDr. Martin Svoboda, endoskopické pracoviště KOC\n\nDatum vydání: 19. 10. 2026\n\nMAKROSKOPICKY\n\n4 válečky šedobílé tkáně délky 3–12 mm, zpracovány celé.\n\nMIKROSKOPICKY\n\nVe vzorcích infiltrace adenokarcinomem tvořeným nepravidelnými, místy splývajícími žláznatými strukturami s jadernou atypií středního až vysokého stupně a výraznou desmoplastickou stromální reakcí. Zastižena perineurální invaze.\n\nImunohistochemicky: CK7 pozitivní, CK19 pozitivní, CK20 negativní, CDX2 negativní, SMAD4 exprese zachována.\n\nZÁVĚR\n\nDuktální adenokarcinom pankreatu, středně až málo diferencovaný (G2–G3), s perineurální invazí. MKN-O 8500/3.\n\nDatum: 19. 10. 2026\n\nMUDr. Radek Pokorný, Ph.D.\n\npatolog\n",
  "01": "<!-- source: 01_Kardiologie_2026-07-20.docx -->\n\nFIKTIVNÍ PACIENTKA – testovací data pro Rakathon 2026\n\nKardiologická ambulance Jesenice (fiktivní)\n\nMUDr. Petr Malý, kardiolog\n\nBudějovická 410, 252 42 Jesenice\n\nAmbulantní zpráva – kontrolní vyšetření\n\nDatum: 20. 7. 2026\n\nPacientka: Alena Procházková\n\nRodné číslo: 635722/1013\n\nBydliště: Za Školou 17, 252 41 Dolní Břežany\n\nZdravotní pojišťovna: 211\n\nDIAGNÓZY\n\nI48.0 Paroxysmální fibrilace síní, CHA₂DS₂-VASc 2 b., HAS-BLED 1 b., na antikoagulační léčbě\n\nI10 Arteriální hypertenze\n\nE78.0 Hypercholesterolémie\n\nSUBJEKTIVNĚ\n\nOd poslední kontroly v lednu 2026 bez palpitací, bez dušnosti, bolesti na hrudi neguje. Zátěž toleruje dobře (2 patra bez zastavení). Otoky dolních končetin neguje. Zažívací obtíže neguje.\n\nOBJEKTIVNĚ\n\nTK 132/80 mmHg, TF 68/min, pravidelná. Výška 165 cm, hmotnost 69 kg. Akce srdeční pravidelná, ozvy ohraničené, bez šelestu. Dýchání čisté, sklípkové. Bez otoků DK.\n\nEKG\n\nSinusový rytmus, 68/min, PQ 0,16 s, QRS 0,09 s, osa intermediární, bez ischemických změn ST-T.\n\nEchokardiografie (orientační)\n\nLK nedilatovaná, normální kinetika, EF LK 60 %. LS 42 mm. Chlopně bez hemodynamicky významné vady. Perikard bez výpotku.\n\nMEDIKACE\n\napixaban 5 mg 1-0-1, bisoprolol 5 mg 1-0-0, perindopril 4 mg 1-0-0, rosuvastatin 10 mg 0-0-1\n\nZÁVĚR A DOPORUČENÍ\n\nStabilní stav, sinusový rytmus, bez recidivy fibrilace síní. Hypertenze kompenzovaná. Medikace beze změn. Kontrola za 6 měsíců (leden 2027).\n\nPřed plánovaným invazivním výkonem s vysokým rizikem krvácení vysadit apixaban 48 hodin předem, bez nutnosti překlenovací léčby.\n\nV Jesenici dne 20. 7. 2026\n\nMUDr. Petr Malý\n\nkardiolog\n\nKopie: MUDr. Tomáš Řezníček, praktický lékař\n",
  "02": "<!-- source: 02_Laborator_2026-09-01.docx -->\n\nFIKTIVNÍ PACIENTKA – testovací data pro Rakathon 2026\n\nLaboratoř LabJih s.r.o. (fiktivní)\n\nKlinická biochemie, hematologie, mikrobiologie\n\nLibušská 300, 142 00 Praha 4\n\nVýsledky laboratorního vyšetření\n\nPacientka: Alena Procházková, RČ 635722/1013, ZP 211\n\nIndikující lékař: MUDr. Tomáš Řezníček, praktický lékař, Dolní Břežany\n\nOdběr: 1. 9. 2026 8:10\n\nVydáno: 4. 9. 2026 (kultivace), 1. 9. 2026 (ostatní)\n\nHEMATOLOGIE – KREVNÍ OBRAZ\n\n| Vyšetření | Výsledek | Jednotky | Ref. meze |\n| --- | --- | --- | --- |\n| Leukocyty | 12,8 H | 10⁹/l | 4,0–10,0 |\n| Erytrocyty | 4,21 | 10¹²/l | 3,80–5,20 |\n| Hemoglobin | 124 | g/l | 120–160 |\n| Hematokrit | 0,37 | 1 | 0,35–0,47 |\n| Trombocyty | 298 | 10⁹/l | 150–400 |\n| Neutrofily | 82 H | % | 45–70 |\n| Lymfocyty | 12 L | % | 20–45 |\n\nKLINICKÁ BIOCHEMIE – SÉRUM\n\n| Vyšetření | Výsledek | Jednotky | Ref. meze |\n| --- | --- | --- | --- |\n| Sodík | 136 | mmol/l | 136–145 |\n| Draslík | 4,0 | mmol/l | 3,5–5,1 |\n| Chloridy | 99 | mmol/l | 98–107 |\n| Urea | 5,1 | mmol/l | 2,8–8,1 |\n| Kreatinin | 78 | µmol/l | 45–84 |\n| Glukóza | 6,4 H | mmol/l | 3,9–5,6 |\n| Bilirubin celkový | 38 H | µmol/l | 2–17 |\n| ALT | 1,92 H | µkat/l | 0,10–0,60 |\n| AST | 1,45 H | µkat/l | 0,10–0,60 |\n| GGT | 4,20 H | µkat/l | 0,10–0,70 |\n| ALP | 3,10 H | µkat/l | 0,58–1,75 |\n| Amyláza | 1,10 | µkat/l | 0,47–1,67 |\n| Lipáza | 0,85 | µkat/l | 0,22–1,00 |\n| CRP | 86 H | mg/l | 0–5 |\n\nMOČ – CHEMICKY\n\n| Vyšetření | Výsledek |  | Ref. |\n| --- | --- | --- | --- |\n| pH | 6,0 |  | 5–7 |\n| Bílkovina | + H |  | neg. |\n| Glukóza | neg. |  | neg. |\n| Ketolátky | neg. |  | neg. |\n| Bilirubin | ++ H |  | neg. |\n| Urobilinogen | norm. |  | norm. |\n| Krev | + H |  | neg. |\n| Leukocyty | ++ H |  | neg. |\n| Nitrity | neg. |  | neg. |\n\nMOČ – SEDIMENT\n\n| Vyšetření | Výsledek | Jednotky | Ref. meze |\n| --- | --- | --- | --- |\n| Erytrocyty | 8 | /µl | 0–5 |\n| Leukocyty | 65 H | /µl | 0–10 |\n| Bakterie | + |  | neg. |\n| Epitelie ploché | ojediněle |  |  |\n| Hlen | + |  |  |\n\nMIKROBIOLOGIE – KULTIVACE MOČI (VÝSLEDEK 4. 9. 2026)\n\nEscherichia coli 10⁴ CFU/ml\n\n| Antibiotikum | Citlivost |  |  |\n| --- | --- | --- | --- |\n| Ampicilin | R |  |  |\n| Amoxicilin/klavulanát | C |  |  |\n| Cefuroxim | C |  |  |\n| Ciprofloxacin | C |  |  |\n| Kotrimoxazol | C |  |  |\n| Nitrofurantoin | C |  |  |\n\nC = citlivý, R = rezistentní. Signifikance nálezu hraniční, interpretovat s ohledem na klinický stav.\n\nVydal:\n\nRNDr. Hana Kolářová\n\nodborný pracovník laboratoře\n",
  "03": "<!-- source: 03_RTG_plic_2026-09-03.docx -->\n\nFIKTIVNÍ PACIENTKA – testovací data pro Rakathon 2026\n\nRadiologické centrum Modřany (fiktivní)\n\nKomořanská 120, 143 00 Praha 4\n\nVýsledek vyšetření – RTG hrudníku PA\n\nPacientka: Alena Procházková, RČ 635722/1013, ZP 211\n\nIndikující lékař: MUDr. Tomáš Řezníček, praktický lékař\n\nDatum vyšetření: 3. 9. 2026\n\nKlinická otázka: febrilie, vyloučit pneumonii\n\nPOPIS\n\nPlicní parenchym bez ložiskových a infiltrativních změn. Hily nerozšířené, strukturně přiměřené. Cévní kresba nezmnožená. Bránice hladká, kostofrenické úhly volné. Srdeční stín nezvětšen. Mediastinum nerozšířeno. Skelet hrudníku bez zjevných patologických změn.\n\nZÁVĚR\n\nBez známek zánětlivých změn plic. Přiměřený nález na srdci a plicích.\n\nDatum: 3. 9. 2026\n\nMUDr. Lucie Hájková\n\nradiolog\n",
  "04": "<!-- source: 04_PL_epikriza_2026-09-04.docx -->\n\nFIKTIVNÍ PACIENTKA – testovací data pro Rakathon 2026\n\nOrdinace praktického lékaře pro dospělé\n\nMUDr. Tomáš Řezníček\n\nNa Návsi 3, 252 41 Dolní Břežany\n\nEpikríza a žádost o vyšetření gastroenterologem\n\nPacientka: Alena Procházková\n\nRodné číslo: 635722/1013\n\nBydliště: Za Školou 17, 252 41 Dolní Břežany\n\nZdravotní pojišťovna: 211\n\nDatum narození: 22. 7. 1963 (63 let)\n\nTelefon: +420 777 000 541\n\nKontaktní osoba: Petra Horká (dcera), tel. +420 777 000 542\n\nEPIKRÍZA\n\n63letá pacientka přišla 1. 9. 2026 pro asi 2 týdny trvající bolesti břicha v epigastriu a pravém podžebří, intermitentní teploty do 38,6 °C se zimnicí, únavu, nechutenství a tmavší moč posledních 5 dní. Dysurii a polakisurii neguje, průjem ani zvracení neguje.\n\nObjektivně TT 38,1 °C, TK 128/78 mmHg, TF 92/min pravidelná. Subikterus sklér. Břicho měkké, palpačně citlivé v epigastriu a pravém podžebří, Murphyho znamení negativní, bez hmatné rezistence. Tapottement bilaterálně negativní.\n\nLaboratorně leukocytóza 12,8, CRP 86 mg/l, cholestáza (bilirubin 38 µmol/l, GGT 4,20, ALP 3,10 µkat/l), v moči bilirubin ++ a leukocyturie, kultivačně E. coli 10⁴ CFU/ml (hraniční). RTG hrudníku 3. 9. bez zánětlivých změn.\n\nZávěr: febrilní stav, suspektní infekce močových cest vs. biliární infekce, cholestatický syndrom nejasné etiologie.\n\nTerapie: od 2. 9. 2026 ciprofloxacin 500 mg 1-0-1 po dobu 7 dní, paracetamol 500 mg při bolesti nebo teplotě max. 4× denně, dostatek tekutin. Při telefonické kontrole 4. 9. afebrilní, bolesti mírnější, moč nadále tmavší.\n\nANAMNÉZA\n\nRA: matka diabetes mellitus 2. typu, otec infarkt myokardu v 70 letech\n\nOA: paroxysmální fibrilace síní od r. 2021 na antikoagulaci (sledována kardiologem, poslední kontrola 20. 7. 2026), arteriální hypertenze, hypercholesterolémie, st. p. hysterektomii pro myomy (2010), v r. 2019 po úmrtí manžela přechodně depresivní ladění, neléčena\n\nFA: apixaban 5 mg 1-0-1, bisoprolol 5 mg 1-0-0, perindopril 4 mg 1-0-0, rosuvastatin 10 mg 0-0-1\n\nAA: neguje\n\nAbusus: nekuřačka, alkohol abstinentka\n\nSA: vdova, žije sama v bytě, dcera bydlí v téže obci\n\nPA: účetní, dosud pracuje\n\nDOPORUČENÍ\n\n1. Vyšetření gastroenterologem pro cholestatický syndrom – objednána na 15. 9. 2026, MUDr. Ivana Křížová, Poliklinika Jižní.\n\n2. Kontrola u PL po dobrání ATB 9. 9. 2026 s kontrolním odběrem.\n\n3. Při návratu teplot, zežloutnutí nebo zhoršení bolestí neprodleně kontaktovat lékaře.\n\nV Dolních Břežanech dne 4. 9. 2026\n\nMUDr. Tomáš Řezníček\n\npraktický lékař, Na Návsi 3, 252 41 Dolní Břežany\n",
  "05": "<!-- source: 05_Gastroenterologie_2026-09-15.docx -->\n\nFIKTIVNÍ PACIENTKA – testovací data pro Rakathon 2026\n\nPoliklinika Jižní (fiktivní)\n\nGastroenterologická ambulance – MUDr. Ivana Křížová\n\nZa Poliklinikou 5, 143 00 Praha 4\n\nAmbulantní zpráva – vstupní vyšetření\n\nDatum: 15. 9. 2026\n\nPacientka: Alena Procházková\n\nRodné číslo: 635722/1013\n\nBydliště: Za Školou 17, 252 41 Dolní Břežany\n\nZdravotní pojišťovna: 211\n\nOdesílající lékař: MUDr. Tomáš Řezníček, praktický lékař\n\nSUBJEKTIVNĚ\n\nOdeslána PL pro cholestázu po febrilní epizodě. Po ciprofloxacinu afebrilní od 4. 9. Přetrvávají tupé bolesti v epigastriu s propagací do zad, horší po jídle a v noci. Nechutenství, úbytek hmotnosti 4 kg za poslední měsíc (z 69 na 65 kg). Moč stále tmavší, stolice občas světlejší. Pruritus neguje. Nauzea občasná, zvracení neguje.\n\nOBJEKTIVNĚ\n\nHmotnost 65 kg. Subikterus sklér. Břicho měkké, palpačně citlivé v epigastriu, bez hmatné rezistence, játra nezvětšena, bez ascitu. Per rektum neprovedeno.\n\nZÁVĚR\n\nCholestatický syndrom s bolestmi v epigastriu propagujícími do zad a úbytkem hmotnosti, st. p. febrilní epizodě léčené ATB. Diferenciálně diagnosticky choledocholitiáza, stenóza žlučových cest, tumor pankreatu.\n\nDOPORUČENÍ\n\n1. UZ břicha – objednána na nejbližší volný termín 29. 9. 2026, RDG pracoviště Polikliniky Jižní.\n\n2. Dle výsledku UZ CT břicha dle pankreatického protokolu, případně EUS.\n\n3. Kontrola v gastroenterologické ambulanci s výsledkem UZ.\n\n4. Pacientka užívá apixaban – před případným invazivním výkonem nutno vysadit 48 h předem.\n\n5. Při teplotách nebo progresi ikteru neprodleně kontaktovat lékaře / LSPP.\n\nV Praze dne 15. 9. 2026\n\nMUDr. Ivana Křížová\n\ngastroenterolog\n\nKopie: MUDr. Tomáš Řezníček, praktický lékař\n",
  "06": "<!-- source: 06_UZ_bricha_2026-09-29.docx -->\n\nFIKTIVNÍ PACIENTKA – testovací data pro Rakathon 2026\n\nPoliklinika Jižní (fiktivní)\n\nRadiodiagnostické pracoviště\n\nZa Poliklinikou 5, 143 00 Praha 4\n\nVýsledek vyšetření – UZ břicha\n\nPacientka: Alena Procházková, RČ 635722/1013, ZP 211\n\nIndikující lékař: MUDr. Ivana Křížová, gastroenterolog\n\nDatum vyšetření: 29. 9. 2026\n\nPOPIS\n\nJátra normální velikosti, homogenní echostruktury, bez ložiskových změn. Intrahepatální žlučovody lehce dilatovány, ductus hepatocholedochus 10 mm. Žlučník mírně distendovaný, stěna 3 mm, bez konkrementů. V hlavě pankreatu hypoechogenní, nehomogenní, neostře ohraničené ložisko 34 × 30 mm. Ductus Wirsungi 4 mm. Vztah ložiska k portomezenterickému soutoku nelze ultrazvukem spolehlivě posoudit. Tělo a kauda pankreatu přehledné jen částečně. Slezina 10 cm, homogenní. Ledviny normální velikosti, bez městnání a konkrementů. Bez volné tekutiny.\n\nZÁVĚR\n\nLožisková léze hlavy pankreatu suspektní z malignity s mírnou dilatací žlučových cest. Doporučeno CT břicha dle pankreatického protokolu, případně EUS.\n\nDatum: 29. 9. 2026\n\nMUDr. Jan Kopecký\n\nradiolog\n",
  "07": "<!-- source: 07_PL_zadost_KOC2_2026-10-02.docx -->\n\nFIKTIVNÍ PACIENTKA – testovací data pro Rakathon 2026\n\nOrdinace praktického lékaře pro dospělé\n\nMUDr. Tomáš Řezníček\n\nNa Návsi 3, 252 41 Dolní Břežany\n\nIČP: 72045318   Tel.: +420 311 000 287\n\nEpikríza a žádost o převzetí do péče KOC\n\nAdresát: Komplexní onkologické centrum Nemocnice Lipová – koordinátor KOC\n\nPacientka: Alena Procházková\n\nRodné číslo: 635722/1013\n\nBydliště: Za Školou 17, 252 41 Dolní Břežany\n\nZdravotní pojišťovna: 211\n\nDatum narození: 22. 7. 1963 (63 let)\n\nTelefon: +420 777 000 541\n\nKontaktní osoba: Petra Horká (dcera), tel. +420 777 000 542\n\nEPIKRÍZA\n\n63letá pacientka sledovaná v naší ordinaci. Od poloviny srpna 2026 bolesti břicha v epigastriu a pravém podžebří, na přelomu srpna a září intermitentní teploty se zimnicí a tmavší moč. Při vyšetření 1. 9. 2026 febrilní (38,1 °C), se subikterem sklér. Provedeny laboratorní odběry včetně vyšetření moči a kultivace a RTG plic. Pro suspektní infekci močových cest vs. biliární infekci léčena ciprofloxacinem 7 dní, poté afebrilní.\n\nPro přetrvávající cholestázu vyšetřena 15. 9. 2026 gastroenterologem, který doporučil UZ břicha. UZ provedené 29. 9. 2026 prokázalo ložisko hlavy pankreatu suspektní z malignity. Gastroenterolog doporučil doplnit CT břicha dle pankreatického protokolu, případně EUS.\n\nTermín CT se nám v dostupných pracovištích nepodařilo zajistit.\n\nPři kontrole dnes bolesti v epigastriu s propagací do zad přetrvávají, zhoršují se po jídle a v noci, na paracetamolu jen částečná úleva. Nechutenství, pokračující úbytek hmotnosti, moč nadále tmavší. Teploty od září neměla. Soběstačná, v práci t. č. v pracovní neschopnosti. Psychicky pacientka velmi úzkostná, špatně spí.\n\nANAMNÉZA\n\nRA: matka diabetes mellitus 2. typu, otec infarkt myokardu v 70 letech\n\nOA: paroxysmální fibrilace síní od r. 2021 na antikoagulaci (kardiolog MUDr. Petr Malý, Jesenice), arteriální hypertenze, hypercholesterolémie, st. p. hysterektomii pro myomy (2010), v r. 2019 po úmrtí manžela přechodně depresivní ladění, neléčena\n\nFA: apixaban 5 mg 1-0-1, bisoprolol 5 mg 1-0-0, perindopril 4 mg 1-0-0, rosuvastatin 10 mg 0-0-1, paracetamol 500 mg při bolesti max. 4× denně\n\nAA: neguje\n\nAbusus: nekuřačka, alkohol abstinentka\n\nSA: vdova, žije sama, dcera bydlí v téže obci\n\nPA: účetní, t. č. v pracovní neschopnosti\n\nPROVEDENÁ VYŠETŘENÍ (VÝSLEDKY K DISPOZICI NA JEDNOTLIVÝCH PRACOVIŠTÍCH)\n\n1. Laboratorní vyšetření 1. 9. 2026 – krevní obraz, biochemie, moč chemicky a sediment, kultivace moči (LabJih)\n\n2. RTG plic 3. 9. 2026 (Radiologické centrum Modřany)\n\n3. Gastroenterologické vyšetření 15. 9. 2026 (MUDr. Ivana Křížová, Poliklinika Jižní)\n\n4. UZ břicha 29. 9. 2026 (RDG pracoviště, Poliklinika Jižní)\n\n5. Kardiologická kontrola 20. 7. 2026 (MUDr. Petr Malý)\n\nŽÁDOST\n\nSuspektní diagnóza: C25.0 – suspektní tumor hlavy pankreatu, cholestatický syndrom\n\nŽádám o převzetí pacientky do péče KOC k dokončení diagnostiky (CT břicha, histologická verifikace) a stanovení dalšího postupu v rámci MDT. Vzhledem k progresi obtíží a nezajištěnému termínu CT prosím o urgentní řešení.\n\nUpozorňuji na antikoagulační léčbu apixabanem – před invazivními výkony nutné vysazení dle doporučení kardiologa. Vzhledem k výrazné úzkosti pacientky prosím o zvážení psychologické podpory.\n\nPacientka je o podezření na nádorové onemocnění informována. Souhlasí se sdílením informací s dcerou.\n\nDěkuji za spolupráci.\n\nV Dolních Břežanech dne 2. 10. 2026\n\nMUDr. Tomáš Řezníček\n\npraktický lékař, Na Návsi 3, 252 41 Dolní Břežany\n",
  "08": "<!-- source: 08_CT_KOC1_2026-10-08.docx -->\n\nFIKTIVNÍ PACIENTKA – testovací data pro Rakathon 2026\n\nKOC Nemocnice Severní (fiktivní)\n\nRadiologická klinika\n\nSeverní 1200, 180 00 Praha 8\n\nVýsledek vyšetření – CT břicha a hrudníku s k. l., pankreatický protokol\n\nPacientka: Alena Procházková, RČ 635722/1013, ZP 211\n\nIndikující lékař: MUDr. Ivana Křížová, gastroenterolog, Poliklinika Jižní\n\nDatum vyšetření: 8. 10. 2026\n\nPOPIS\n\nV hlavě pankreatu hypodenzní, neostře ohraničené ložisko 35 × 31 mm. Ložisko obkružuje v. mesenterica superior v rozsahu cca 200° obvodu s nepravidelností kontury a zúžením lumen v délce 18 mm; proximální i distální segment VMS je vhodný k případné rekonstrukci. V. portae nad konfluencí průchodná. Kontakt tumoru s a. mesenterica superior do 150° obvodu, bez zúžení lumen. Truncus coeliacus a a. hepatica communis bez kontaktu s tumorem. A. gastroduodenalis v kontaktu s tumorem.\n\nDuctus hepatocholedochus 11 mm, intrahepatální žlučovody lehce dilatovány. Ductus Wirsungi 4 mm, parenchym těla a kaudy atrofický. Peripankreaticky uzlina 12 × 9 mm, suspektní. Paraaortální uzliny nezvětšené. Játra bez ložiskových změn. Bez ascitu, peritoneum bez nodulací.\n\nHrudník: plíce bez ložiskových změn, bez fluidothoraxu. Mediastinální a hilové uzliny nezvětšeny. Skelet bez osteolytických či osteoplastických ložisek.\n\nZÁVĚR\n\nTumor hlavy pankreatu 35 mm s venózním postižením VMS se zúžením lumen a s kontaktem s AMS. Suspektní peripankreatická uzlina. Bez známek vzdálených metastáz.\n\nDatum: 8. 10. 2026\n\nMUDr. Daniel Fiala, Ph.D.\n\nradiolog\n",
  "09": "<!-- source: 09_Biopsie_vykon_KOC2_2026-10-12.docx -->\n\nFIKTIVNÍ PACIENTKA – testovací data pro Rakathon 2026\n\nKOC Nemocnice Lipová (fiktivní)\n\nEndoskopické pracoviště, Interní gastroenterologická klinika\n\nNemocniční 15, 140 00 Praha 4\n\nProtokol o výkonu – EUS-FNB\n\nPacientka: Alena Procházková, RČ 635722/1013, ZP 211\n\nDatum výkonu: 12. 10. 2026\n\nVýkon: endosonografie s biopsií ložiska hlavy pankreatu (EUS-FNB)\n\nIndikace: histologická verifikace ložiska hlavy pankreatu\n\nPŘÍPRAVA\n\nNalačno od půlnoci. Apixaban vysazen 48 h před výkonem (poslední dávka 18. 10. 2026 večer). Informovaný souhlas podepsán.\n\nANESTEZIE A MONITORACE\n\nAnalgosedace propofol 180 mg i.v. frakcionovaně za asistence anesteziologa. Monitorace SpO₂, TK a EKG, oxygenoterapie nosními brýlemi 2 l/min.\n\nPOPIS VÝKONU\n\nLineární echoendoskop zaveden bez obtíží přes jícen a žaludek do bulbu a sestupného raménka duodena. Z transduodenální polohy zobrazeno hypoechogenní nehomogenní ložisko v hlavě pankreatu 33 × 29 mm. Barevným dopplerem ověřena dráha vpichu bez interponovaných cév. Provedeny 3 průchody jehlou FNB 22G technikou slow-pull, 12–15 pohybů na průchod. Makroskopicky získány dostatečné válečky tkáně, fixovány ve formolu a odeslány k histologickému vyšetření. Po výkonu v místě vpichu minimální krvácení, spontánně zastavené. Endoskop vytažen, bez komplikací.\n\nDOPORUČENÍ\n\n2 hodiny klid na lůžku, poté tekutiny per os. Při nekomplikovaném průběhu apixaban znovu od 21. 10. 2026 ráno. Výsledek histologie do 3 pracovních dnů.\n\nV Praze dne 12. 10. 2026\n\nMUDr. Martin Svoboda\n\ngastroenterolog, endoskopista\n"
}
